<script lang="ts" setup>
import { ref, computed, onMounted, onUnmounted } from 'vue';
import {
  ListRules, AddRule, UpdateRule, DeleteRule, Interfaces,
  Groups, ApplyGroup, DeleteGroupRules, SetGroupEnabled,
  ListProxies, ListXray, BulkUpdateRules, RuleExitIP,
} from '../../wailsjs/go/main/App';
import type { ipc } from '../../wailsjs/go/models';
import GroupIcon from './GroupIcon.vue';

// Local shape for a proxy row — same fields as ipc.ProxyDTO; using a
// local type means the component still type-checks while wailsjs/models
// is being regenerated by Wails on the next dev/build.
type ProxyRow = {
  id: number;
  name: string;
  protocol: string;
  host: string;
  port: number;
  username: string;
  hasPassword: boolean;
  createdAt: string;
  updatedAt: string;
};

// Local mirror of XrayDTO — see above for the rationale.
type XrayRow = {
  id: number;
  name: string;
  outbound: string;
  socksPort: number;
  enabled: boolean;
  createdAt: string;
  updatedAt: string;
};

const emit = defineEmits<{ (e: 'changed'): void }>();

const rules = ref<ipc.RuleDTO[]>([]);
const interfaces = ref<ipc.InterfaceDTO[]>([]);
const proxies = ref<ProxyRow[]>([]);
const xrays = ref<XrayRow[]>([]);
const knownGroups = ref<ipc.GroupDTO[]>([]);
const error = ref<string>('');
const pendingDelete = ref<number | null>(null);
const pendingDeleteGroup = ref<string | null>(null);
const search = ref<string>('');
// Per-rule exit-IP probe results, keyed by rule id. Fetched
// automatically after rules load (bounded concurrency) and re-fetchable
// per row via the retry button. The daemon caches each probe for a few
// minutes, so the auto-fetch and any retries stay cheap.
const exitInfo = ref<Record<number, ipc.ExitIPResult>>({});
const exitLoading = ref<Record<number, boolean>>({});
// Which rows have their exit IP revealed (default: masked).
const revealedExitIPs = ref<Record<number, boolean>>({});
let pendingDeleteTimer: number | undefined;
let pendingDeleteGroupTimer: number | undefined;
let ifaceTimer: number | undefined;

function normalizePattern(p: string): string {
  return p.toLowerCase().trim().replace(/\.$/, '');
}

const sleep = (ms: number) => new Promise(r => setTimeout(r, ms));

// Turn a 2-letter ISO country code into its flag emoji.
function flagEmoji(cc?: string): string {
  if (!cc || cc.length !== 2) return '';
  const base = 0x1f1e6;
  const up = cc.toUpperCase();
  return String.fromCodePoint(base + up.charCodeAt(0) - 65, base + up.charCodeAt(1) - 65);
}

// maskIP hides the host-specific part of an IP address.
// IPv4: keeps first two octets → 104.16.*.*   IPv6: keeps first group.
function maskIP(ip: string): string {
  if (!ip) return '';
  if (ip.includes(':')) return ip.split(':')[0] + ':…';
  const p = ip.split('.');
  return p.length === 4 ? `${p[0]}.${p[1]}.*.*` : ip;
}

function toggleExitReveal(id: number) {
  revealedExitIPs.value = { ...revealedExitIPs.value, [id]: !revealedExitIPs.value[id] };
}

// Probe (or re-probe) the public exit IP a rule's matched traffic
// egresses through. Result/failure both land in exitInfo so the row can
// render the IP inline or explain why it couldn't be determined.
async function checkExitIP(r: ipc.RuleDTO) {
  exitLoading.value[r.id] = true;
  try {
    exitInfo.value[r.id] = await RuleExitIP(r.id);
  } catch (e: any) {
    exitInfo.value[r.id] = {
      interface: r.interface, exitIp: '', country: '', region: '', city: '',
      probed: false, message: e?.message || String(e),
    } as ipc.ExitIPResult;
  } finally {
    exitLoading.value[r.id] = false;
  }
}

// Auto-fetch exit IPs for every non-block rule that doesn't already have
// a result, with a small concurrency cap so the daemon isn't slammed and
// rows fill in progressively. Called after each rules refresh; rules
// already probed (or in flight) are skipped, so it's cheap to re-run.
const EXIT_IP_CONCURRENCY = 4;
async function autoFetchExitIPs() {
  const pending = rules.value.filter(
    r => r.action !== 'block' && !exitInfo.value[r.id] && !exitLoading.value[r.id],
  );
  if (pending.length === 0) return;
  let i = 0;
  const worker = async () => {
    while (i < pending.length) await checkExitIP(pending[i++]);
  };
  await Promise.all(Array.from({ length: Math.min(EXIT_IP_CONCURRENCY, pending.length) }, worker));
}

// A rule "belongs to" a group when its pattern sits inside the scope
// of any of the group's curated patterns. Mirrors the daemon's
// ruleCoveredByGroupPattern (and the engine's actual wildcard match):
//   group "*.openai.com" covers  openai.com, *.openai.com, api.openai.com, *.api.openai.com
//   group "openai.com"   covers  only the exact "openai.com"
// So a hand-typed rule like "chatgpt.com" lands in OpenAI because
// OpenAI's group lists "*.chatgpt.com".
function ruleCoveredBy(rulePat: string, groupPat: string): boolean {
  const rp = normalizePattern(rulePat);
  const gp = normalizePattern(groupPat);
  if (!rp || !gp) return false;
  if (rp === gp) return true;
  if (!gp.startsWith('*.')) return false;
  const suffix = gp.slice(2);
  const body = rp.startsWith('*.') ? rp.slice(2) : rp;
  return body === suffix || body.endsWith('.' + suffix);
}

function groupForRule(r: ipc.RuleDTO): ipc.GroupDTO | undefined {
  for (const g of knownGroups.value) {
    for (const p of g.patterns) {
      if (ruleCoveredBy(r.pattern, p)) return g;
    }
  }
  return undefined;
}

// "Lazy" group match: a query hits a group if it's a substring of the
// key, display name, description, or any pattern. Same matcher is used
// for the quick-add cards and to surface a group's rules in the list.
function matchesGroup(g: ipc.GroupDTO, q: string): boolean {
  if (!q) return true;
  if (g.key.toLowerCase().includes(q)) return true;
  if (g.displayName.toLowerCase().includes(q)) return true;
  if (g.description.toLowerCase().includes(q)) return true;
  return g.patterns.some(p => p.toLowerCase().includes(q));
}

const filteredGroups = computed<ipc.GroupDTO[]>(() => {
  const q = search.value.trim().toLowerCase();
  if (!q) return knownGroups.value;
  return knownGroups.value.filter(g => matchesGroup(g, q));
});

const filteredRules = computed<ipc.RuleDTO[]>(() => {
  const q = search.value.trim().toLowerCase();
  if (!q) return rules.value;
  return rules.value.filter(r => {
    if (r.pattern.toLowerCase().includes(q)) return true;
    const g = groupForRule(r);
    return g ? matchesGroup(g, q) : false;
  });
});

// Sectioned view: an array of {group | null, rules[]}, in display
// order. Groups come first (in the registry's order), then an
// "Ungrouped" bucket. Empty sections (after search filter) are
// dropped so the user sees only what matches.
type Section = { group: ipc.GroupDTO | null; rules: ipc.RuleDTO[] };

const sections = computed<Section[]>(() => {
  const byGroup = new Map<string, ipc.RuleDTO[]>();
  const ungrouped: ipc.RuleDTO[] = [];
  for (const r of filteredRules.value) {
    const g = groupForRule(r);
    if (g) {
      const list = byGroup.get(g.key) ?? [];
      list.push(r);
      byGroup.set(g.key, list);
    } else {
      ungrouped.push(r);
    }
  }
  const out: Section[] = [];
  for (const g of knownGroups.value) {
    const list = byGroup.get(g.key);
    if (list && list.length) out.push({ group: g, rules: list });
  }
  if (ungrouped.length) out.push({ group: null, rules: ungrouped });
  return out;
});

// Bulk-state for a group: 'on' if every rule enabled, 'off' if every
// disabled, 'mixed' otherwise. Drives the section-header toggle.
function groupEnabledState(rs: ipc.RuleDTO[]): 'on' | 'off' | 'mixed' {
  if (!rs.length) return 'off';
  const onCount = rs.filter(r => r.enabled).length;
  if (onCount === rs.length) return 'on';
  if (onCount === 0) return 'off';
  return 'mixed';
}

async function setGroupEnabledAll(g: ipc.GroupDTO, enabled: boolean) {
  try {
    await SetGroupEnabled(g.key, enabled);
    await refresh();
    emit('changed');
  } catch (e: any) {
    error.value = e?.message || String(e);
  }
}

// Collapse/expand state per section. Group sections start collapsed
// to keep the list scannable; the ungrouped bucket (the user's own
// rules) starts expanded. Applying a group expands its section so the
// freshly created rules are visible. User toggles persist for the
// lifetime of the component (no localStorage — nothing to migrate).
const expanded = ref<Set<string>>(new Set(['__ungrouped__']));
function sectionKey(g: ipc.GroupDTO | null): string {
  return g ? g.key : '__ungrouped__';
}
function isCollapsed(g: ipc.GroupDTO | null): boolean {
  return !expanded.value.has(sectionKey(g));
}
function toggleCollapse(g: ipc.GroupDTO | null) {
  const k = sectionKey(g);
  const next = new Set(expanded.value);
  if (next.has(k)) next.delete(k); else next.add(k);
  expanded.value = next;
}
function expandSection(key: string) {
  if (expanded.value.has(key)) return;
  const next = new Set(expanded.value);
  next.add(key);
  expanded.value = next;
}

function askDeleteGroup(g: ipc.GroupDTO) {
  if (pendingDeleteGroup.value === g.key) {
    confirmDeleteGroup(g);
    return;
  }
  pendingDeleteGroup.value = g.key;
  if (pendingDeleteGroupTimer) window.clearTimeout(pendingDeleteGroupTimer);
  pendingDeleteGroupTimer = window.setTimeout(() => {
    pendingDeleteGroup.value = null;
  }, 3000);
}

async function confirmDeleteGroup(g: ipc.GroupDTO) {
  if (pendingDeleteGroupTimer) window.clearTimeout(pendingDeleteGroupTimer);
  pendingDeleteGroup.value = null;
  try {
    await DeleteGroupRules(g.key);
    await refresh();
    emit('changed');
  } catch (e: any) {
    error.value = e.toString();
  }
}

// Group-apply working state. When the user clicks a group card, this
// gets populated with the same shape as `draft` so the same binding
// picker UI can be reused.
const groupApply = ref<{
  key: string;
  action: 'block' | 'route';
  binding: 'iface' | 'proxy' | 'xray';
  iface: string;
  proxies: string[];
  xrays: string[];
  enabled: boolean;
} | null>(null);

function openGroupForm(g: ipc.GroupDTO) {
  groupApply.value = {
    key: g.key,
    action: 'block',
    binding: 'iface',
    iface: '',
    proxies: [],
    xrays: [],
    enabled: true,
  };
}

function closeGroupForm() { groupApply.value = null; }

function toggleGroupProxy(name: string) {
  if (!groupApply.value) return;
  const idx = groupApply.value.proxies.indexOf(name);
  if (idx >= 0) groupApply.value.proxies.splice(idx, 1);
  else groupApply.value.proxies.push(name);
}

function toggleGroupXray(name: string) {
  if (!groupApply.value) return;
  const idx = groupApply.value.xrays.indexOf(name);
  if (idx >= 0) groupApply.value.xrays.splice(idx, 1);
  else groupApply.value.xrays.push(name);
}

function groupInterfaceField(): string {
  const g = groupApply.value;
  if (!g || g.action !== 'route') return '';
  if (g.binding === 'proxy' && g.proxies.length > 0) return `proxy:${g.proxies.join(',')}`;
  if (g.binding === 'xray' && g.xrays.length > 0) return `xray:${g.xrays.join(',')}`;
  if (g.binding === 'iface') return g.iface;
  return '';
}

function groupApplyValid(): boolean {
  const g = groupApply.value;
  if (!g) return false;
  if (g.action === 'block') return true;
  if (g.binding === 'iface') return !!g.iface;
  if (g.binding === 'proxy') return g.proxies.length > 0;
  if (g.binding === 'xray') return g.xrays.length > 0;
  return false;
}

async function applyGroup() {
  const g = groupApply.value;
  if (!g || !groupApplyValid()) return;
  try {
    const result = await ApplyGroup(g.key, g.action, groupInterfaceField(), g.enabled);
    const created = result.created?.length || 0;
    const skipped = result.skipped?.length || 0;
    error.value = '';
    if (skipped > 0) {
      error.value = `Created ${created} rule(s); ${skipped} pattern(s) skipped (already exist).`;
    }
    groupApply.value = null;
    expandSection(g.key);
    await refresh();
    emit('changed');
  } catch (e: any) {
    error.value = e?.message || String(e);
  }
}

function groupByKey(key: string): ipc.GroupDTO | undefined {
  return knownGroups.value.find(g => g.key === key);
}

// Action model:
//   block — return NXDOMAIN
//   route — let through and pin the resolved IPs to a binding
//
// allow exists in the daemon for "explicit pass-through that
// overrides a broader block" but is not exposed in the UI — the
// implicit default for unmatched domains is already "allow".
const draft = ref({
  pattern: '',
  action: 'block' as 'block' | 'route',
  // Only meaningful when action === 'route':
  binding: 'iface' as 'iface' | 'proxy' | 'xray',
  iface: '',
  proxies: [] as string[],
  xrays: [] as string[],
  enabled: true,
});

function draftInterfaceField(): string {
  if (draft.value.action !== 'route') return '';
  if (draft.value.binding === 'proxy' && draft.value.proxies.length > 0) {
    return `proxy:${draft.value.proxies.join(',')}`;
  }
  if (draft.value.binding === 'xray' && draft.value.xrays.length > 0) {
    return `xray:${draft.value.xrays.join(',')}`;
  }
  if (draft.value.binding === 'iface') return draft.value.iface;
  return '';
}

function draftIsValid(): boolean {
  if (!draft.value.pattern.trim()) return false;
  if (draft.value.action === 'block') return true;
  // route requires a non-empty binding
  if (draft.value.binding === 'iface') return !!draft.value.iface;
  if (draft.value.binding === 'proxy') return draft.value.proxies.length > 0;
  if (draft.value.binding === 'xray') return draft.value.xrays.length > 0;
  return false;
}

function toggleDraftProxy(name: string) {
  const idx = draft.value.proxies.indexOf(name);
  if (idx >= 0) {
    draft.value.proxies.splice(idx, 1);
  } else {
    draft.value.proxies.push(name);
  }
}

function toggleDraftXray(name: string) {
  const idx = draft.value.xrays.indexOf(name);
  if (idx >= 0) draft.value.xrays.splice(idx, 1);
  else draft.value.xrays.push(name);
}

// ---- Bulk selection + retarget ---------------------------------------
//
// The bulk toolbar lets the user retarget many rules to a new
// (action, interface) pair in one IPC round-trip. Selection is a Set of
// rule IDs so toggling stays O(1) regardless of how many rules are
// loaded. We deliberately preserve selection across `refresh()` —
// stale IDs are tolerated by the daemon (it skips not-found entries).
//
// "Select all visible" respects the search filter so the user can
// type e.g. `xray:old-name` into the search, hit Select all, and
// retarget the whole filtered set to a new xray entry in one step.

const selected = ref<Set<number>>(new Set());

function isSelected(id: number): boolean {
  return selected.value.has(id);
}

function toggleSelected(id: number) {
  const next = new Set(selected.value);
  if (next.has(id)) next.delete(id); else next.add(id);
  selected.value = next;
}

function clearSelection() {
  selected.value = new Set();
}

function selectAllVisible() {
  const next = new Set<number>();
  for (const r of filteredRules.value) next.add(r.id);
  selected.value = next;
}

const selectedCount = computed<number>(() => selected.value.size);

function sectionSelectionState(rs: ipc.RuleDTO[]): 'all' | 'some' | 'none' {
  if (!rs.length) return 'none';
  let on = 0;
  for (const r of rs) if (selected.value.has(r.id)) on++;
  if (on === 0) return 'none';
  if (on === rs.length) return 'all';
  return 'some';
}

function toggleSection(rs: ipc.RuleDTO[]) {
  const next = new Set(selected.value);
  const state = sectionSelectionState(rs);
  if (state === 'all') {
    for (const r of rs) next.delete(r.id);
  } else {
    for (const r of rs) next.add(r.id);
  }
  selected.value = next;
}

// Editor panel state, mirroring `draft` minus pattern/enabled.
type BulkState = {
  action: 'block' | 'route';
  binding: 'iface' | 'proxy' | 'xray';
  iface: string;
  proxies: string[];
  xrays: string[];
};
const bulk = ref<BulkState | null>(null);

function openBulk() {
  bulk.value = {
    action: 'block',
    binding: 'iface',
    iface: '',
    proxies: [],
    xrays: [],
  };
}

function closeBulk() { bulk.value = null; }

function toggleBulkProxy(name: string) {
  if (!bulk.value) return;
  const idx = bulk.value.proxies.indexOf(name);
  if (idx >= 0) bulk.value.proxies.splice(idx, 1);
  else bulk.value.proxies.push(name);
}

function toggleBulkXray(name: string) {
  if (!bulk.value) return;
  const idx = bulk.value.xrays.indexOf(name);
  if (idx >= 0) bulk.value.xrays.splice(idx, 1);
  else bulk.value.xrays.push(name);
}

function bulkInterfaceField(): string {
  const b = bulk.value;
  if (!b || b.action !== 'route') return '';
  if (b.binding === 'proxy' && b.proxies.length > 0) return `proxy:${b.proxies.join(',')}`;
  if (b.binding === 'xray' && b.xrays.length > 0) return `xray:${b.xrays.join(',')}`;
  if (b.binding === 'iface') return b.iface;
  return '';
}

function bulkIsValid(): boolean {
  const b = bulk.value;
  if (!b) return false;
  if (b.action === 'block') return true;
  if (b.binding === 'iface') return !!b.iface;
  if (b.binding === 'proxy') return b.proxies.length > 0;
  if (b.binding === 'xray') return b.xrays.length > 0;
  return false;
}

async function applyBulk() {
  const b = bulk.value;
  if (!b || !bulkIsValid() || selected.value.size === 0) return;
  try {
    const ids = [...selected.value];
    const result = await BulkUpdateRules(ids, b.action, bulkInterfaceField());
    const affected = result?.affected ?? 0;
    error.value = '';
    if (affected < ids.length) {
      error.value = `Updated ${affected} of ${ids.length} rule(s); the rest were missing.`;
    }
    selected.value = new Set();
    bulk.value = null;
    await refresh();
    emit('changed');
  } catch (e: any) {
    error.value = e?.message || String(e);
  }
}

// ---- Inline edit ------------------------------------------------------

type EditState = {
  id: number;
  pattern: string;
  action: 'block' | 'route';
  binding: 'iface' | 'proxy' | 'xray';
  iface: string;
  proxies: string[];
  xrays: string[];
  enabled: boolean;
};

const editing = ref<EditState | null>(null);

function beginEdit(r: ipc.RuleDTO) {
  let binding: 'iface' | 'proxy' | 'xray' = 'iface';
  let iface = '';
  let proxyNames: string[] = [];
  let xrayNames: string[] = [];
  if (r.interface.startsWith('app:')) {
    // Legacy app-bound rules are being removed daemon-side; degrade
    // gracefully to an empty interface binding so editing doesn't crash.
    binding = 'iface';
    iface = '';
  } else if (r.interface.startsWith('proxy:')) {
    binding = 'proxy';
    proxyNames = r.interface.substring(6).split(',').map(s => s.trim()).filter(Boolean);
  } else if (r.interface.startsWith('xray:')) {
    binding = 'xray';
    xrayNames = r.interface.substring(5).split(',').map(s => s.trim()).filter(Boolean);
  } else if (r.interface) {
    binding = 'iface';
    iface = r.interface;
  }
  // Legacy `allow` rows (pre-action-model split) collapse to `route`
  // when they had an interface, otherwise to `block` for editing.
  const action: 'block' | 'route' = r.action === 'route' ? 'route'
    : (r.action === 'allow' && r.interface) ? 'route'
    : (r.action === 'block') ? 'block'
    : 'block';
  editing.value = {
    id: r.id,
    pattern: r.pattern,
    action,
    binding,
    iface,
    proxies: proxyNames,
    xrays: xrayNames,
    enabled: r.enabled,
  };
}

function cancelEdit() { editing.value = null; }

function editingInterfaceField(): string {
  const e = editing.value;
  if (!e || e.action !== 'route') return '';
  if (e.binding === 'proxy' && e.proxies.length > 0) return `proxy:${e.proxies.join(',')}`;
  if (e.binding === 'xray' && e.xrays.length > 0) return `xray:${e.xrays.join(',')}`;
  if (e.binding === 'iface') return e.iface;
  return '';
}

function editingIsValid(): boolean {
  const e = editing.value;
  if (!e || !e.pattern.trim()) return false;
  if (e.action === 'block') return true;
  if (e.binding === 'iface') return !!e.iface;
  if (e.binding === 'proxy') return e.proxies.length > 0;
  if (e.binding === 'xray') return e.xrays.length > 0;
  return false;
}

function toggleEditingProxy(name: string) {
  if (!editing.value) return;
  const idx = editing.value.proxies.indexOf(name);
  if (idx >= 0) editing.value.proxies.splice(idx, 1);
  else editing.value.proxies.push(name);
}

function toggleEditingXray(name: string) {
  if (!editing.value) return;
  const idx = editing.value.xrays.indexOf(name);
  if (idx >= 0) editing.value.xrays.splice(idx, 1);
  else editing.value.xrays.push(name);
}

async function saveEdit() {
  const e = editing.value;
  if (!editingIsValid()) return;
  try {
    await UpdateRule(e!.id, e!.pattern.trim(), e!.action, editingInterfaceField(), e!.enabled);
    editing.value = null;
    await refresh();
    emit('changed');
  } catch (err: any) {
    error.value = err?.message || String(err);
  }
}

async function refresh() {
  try {
    rules.value = (await ListRules()) || [];
    interfaces.value = (await Interfaces()) || [];
    proxies.value = ((await ListProxies()) || []) as unknown as ProxyRow[];
    xrays.value = ((await ListXray()) || []) as unknown as XrayRow[];
    if (knownGroups.value.length === 0) {
      knownGroups.value = (await Groups()) || [];
    }
    error.value = '';
    // Drop cached exit IPs for rules that no longer exist or whose
    // binding changed, so stale entries don't linger, then auto-fetch
    // any rule still missing a result. Fire-and-forget — the rows fill
    // in as each probe returns.
    const live = new Map(rules.value.map(r => [r.id, r.interface]));
    for (const idStr of Object.keys(exitInfo.value)) {
      const id = Number(idStr);
      if (!live.has(id) || exitInfo.value[id].interface !== live.get(id)) {
        delete exitInfo.value[id];
        delete revealedExitIPs.value[id];
      }
    }
    autoFetchExitIPs();
  } catch (e: any) {
    error.value = e?.message || String(e);
  }
}

async function add() {
  if (!draftIsValid()) return;
  try {
    await AddRule(draft.value.pattern.trim(), draft.value.action,
      draftInterfaceField(),
      draft.value.enabled);
    draft.value.pattern = '';
    draft.value.iface = '';
    draft.value.proxies = [];
    draft.value.xrays = [];
    await refresh();
    emit('changed');
  } catch (e: any) {
    error.value = e?.message || String(e);
  }
}

async function toggle(r: ipc.RuleDTO) {
  try {
    await UpdateRule(r.id, r.pattern, r.action, r.interface, !r.enabled);
    await refresh();
    emit('changed');
  } catch (e: any) {
    error.value = e?.message || String(e);
  }
}

function askDelete(r: ipc.RuleDTO) {
  if (pendingDelete.value === r.id) {
    confirmDelete(r);
    return;
  }
  pendingDelete.value = r.id;
  if (pendingDeleteTimer) window.clearTimeout(pendingDeleteTimer);
  pendingDeleteTimer = window.setTimeout(() => {
    pendingDelete.value = null;
  }, 3000);
}

async function confirmDelete(r: ipc.RuleDTO) {
  if (pendingDeleteTimer) window.clearTimeout(pendingDeleteTimer);
  pendingDelete.value = null;
  try {
    await DeleteRule(r.id);
    await refresh();
    emit('changed');
  } catch (e: any) {
    error.value = e?.message || String(e);
  }
}


async function refreshLive() {
  // Polled every few seconds: interfaces so chips reflect live
  // "running" state without requiring a rule edit. Rules themselves
  // don't refresh here — they only change on user action.
  try {
    interfaces.value = (await Interfaces()) || [];
  } catch (_) { /* ignore — keep last good */ }
}

function ifaceLabel(i: ipc.InterfaceDTO): string {
  return i.owner ? `${i.name} — ${i.owner}` : i.name;
}

// Rule binding helpers. The `interface` field on a Rule can be:
//   ''            → default route
//   'utunN'       → fixed interface
//   'proxy:NAME'  → routed through an upstream HTTP/SOCKS5 proxy
//   'xray:NAME'   → routed through an embedded xray-core outbound
function ruleIsProxy(field: string): boolean { return field.startsWith('proxy:'); }

// "proxy:work,home" → ["work","home"]
function ruleProxyKeys(field: string): string[] {
  return field.replace(/^proxy:/, '').split(',').map(s => s.trim()).filter(Boolean);
}

function ruleIsXray(field: string): boolean { return field.startsWith('xray:'); }

// "xray:a,b" → ["a","b"]
function ruleXrayNames(field: string): string[] {
  return field.replace(/^xray:/, '').split(',').map(s => s.trim()).filter(Boolean);
}

function xrayByName(name: string): XrayRow | undefined {
  return xrays.value.find(x => x.name === name);
}

function xrayStatusBadge(name: string): string {
  const x = xrayByName(name);
  if (!x) return '?';
  return x.enabled ? 'on' : 'off';
}

function xrayStatusLabel(name: string): string {
  const x = xrayByName(name);
  if (!x) return `${name} — xray entry no longer exists`;
  return x.enabled ? `xray entry "${name}" enabled` : `xray entry "${name}" disabled`;
}

function proxyByName(name: string): ProxyRow | undefined {
  return proxies.value.find(p => p.name === name);
}

// One-word "live state" badge for a proxy reference. Phase A doesn't
// have a real health check, so we just report whether the proxy is
// configured ("ok") or missing from the store ("?"). Phase B will
// replace this with a real reachability check.
function proxyStatusBadge(name: string): string {
  return proxyByName(name) ? 'ok' : '?';
}

function proxyStatusLabel(name: string): string {
  const p = proxyByName(name);
  if (!p) return `${name} — proxy no longer exists`;
  return `${p.protocol}://${p.host}:${p.port}`;
}

// True if a rule's saved binding can't be honoured right now.
function bindingDown(field: string): boolean {
  if (!field) return false;
  if (ruleIsProxy(field)) {
    const names = ruleProxyKeys(field);
    return !names.some(n => !!proxyByName(n));
  }
  if (ruleIsXray(field)) {
    const names = ruleXrayNames(field);
    return !names.some(n => {
      const x = xrayByName(n);
      return !!x && x.enabled;
    });
  }
  return !interfaces.value.some(i => i.name === field);
}


onMounted(() => {
  refresh();
  ifaceTimer = window.setInterval(refreshLive, 2000);
});
onUnmounted(() => { if (ifaceTimer) window.clearInterval(ifaceTimer); });
</script>

