            <div class="row" style="gap: 0">
              <button :class="['seg', {active: bulk.binding === 'iface'}]" @click="bulk.binding = 'iface'">Interface</button>
              <button :class="['seg', {active: bulk.binding === 'proxy'}]" @click="bulk.binding = 'proxy'">Proxy</button>
