    </div>

    <div v-for="sec in sections" :key="sec.group?.key || '__ungrouped__'"
         class="rule-section">
      <!-- Section header -->
      <div class="section-header">
        <!-- Tri-state section checkbox: ticks every rule in this
             section when none/some are selected; clears the section
             when all are already selected. Uses the indeterminate DOM
             property for the "some" state. -->
        <input type="checkbox"
               class="section-check"
               :checked="sectionSelectionState(sec.rules) === 'all'"
               :indeterminate.prop="sectionSelectionState(sec.rules) === 'some'"
               @change="toggleSection(sec.rules)"
               :title="sectionSelectionState(sec.rules) === 'all' ? 'Deselect all rules in this section' : 'Select every rule in this section'" />
        <button class="caret-btn" @click="toggleCollapse(sec.group)"
                :title="isCollapsed(sec.group) ? 'Expand' : 'Collapse'">
          {{ isCollapsed(sec.group) ? '▸' : '▾' }}
        </button>
        <div class="row" style="gap: 8px; align-items: center; flex: 1; cursor: pointer"
             @click="toggleCollapse(sec.group)">
          <GroupIcon v-if="sec.group" :group-key="sec.group.key" :size="20" />
          <strong v-if="sec.group">{{ sec.group.displayName }}</strong>
          <strong v-else style="color: var(--text-dim)">Ungrouped</strong>
          <span class="muted" style="font-size: 11px">
            {{ sec.rules.length }} {{ sec.rules.length === 1 ? 'rule' : 'rules' }}
          </span>
          <!-- State pill: read-only summary, click goes to collapse -->
          <span v-if="sec.group" class="state-pill" :class="'state-' + groupEnabledState(sec.rules)">
            {{ groupEnabledState(sec.rules) === 'on' ? 'all on'
              : groupEnabledState(sec.rules) === 'off' ? 'all off' : 'mixed' }}
          </span>
        </div>
        <!-- Bulk actions: groups only. Ungrouped section is just a label. -->
        <div v-if="sec.group" class="row" style="gap: 6px; align-items: center">
          <button class="bulk-btn"
                  :disabled="groupEnabledState(sec.rules) === 'on'"
                  @click="setGroupEnabledAll(sec.group, true)"
                  title="Turn every rule in this group on">
            Enable all
          </button>
          <button class="bulk-btn"
                  :disabled="groupEnabledState(sec.rules) === 'off'"
                  @click="setGroupEnabledAll(sec.group, false)"
                  title="Turn every rule in this group off">
            Disable all
          </button>
          <button :class="pendingDeleteGroup === sec.group.key ? 'danger primary' : 'danger'"
                  @click="askDeleteGroup(sec.group)">
            {{ pendingDeleteGroup === sec.group.key ? 'Confirm delete?' : 'Delete all' }}
          </button>
        </div>
      </div>

      <!-- Section body: same row template as before, just in its own table.
           Collapsed sections hide the table entirely so the user can
           scan the page by group headers alone. -->
      <table v-if="!isCollapsed(sec.group)" class="section-table">
        <thead>
          <tr>
            <th style="width: 28px"></th>
            <th>Pattern</th>
            <th>Action</th>
            <th>Interface</th>
            <th>Enabled</th>
            <th></th>
          </tr>
        </thead>
        <tbody>
          <template v-for="r in sec.rules" :key="r.id">
            <tr v-if="editing?.id !== r.id"
                :class="{'rule-iface-down': r.action === 'route' && bindingDown(r.interface), 'rule-selected': isSelected(r.id)}">
              <td style="text-align: center">
                <input type="checkbox"
                       :checked="isSelected(r.id)"
                       @change="toggleSelected(r.id)" />
              </td>
              <td><code>{{ r.pattern }}</code></td>
              <td>
                <span :class="['tag', r.action === 'block' ? 'tag-block' : 'tag-route']">
                  {{ r.action }}
                </span>
                <span v-if="r.action === 'route' && bindingDown(r.interface)"
                      class="tag tag-block" style="margin-left: 6px"
                      :title="ruleIsProxy(r.interface) ? 'Proxy missing — referenced proxy no longer exists'
                            : ruleIsXray(r.interface) ? 'No referenced xray entry is enabled — queries return NXDOMAIN'
                            : 'Configured interface is not up — queries return NXDOMAIN until it comes back'">
                  ⚠ {{ ruleIsProxy(r.interface) ? 'proxy missing'
                       : ruleIsXray(r.interface) ? 'xray off'
                       : 'iface down' }}
                </span>
              </td>
              <td>
                <div v-if="r.action === 'route' && ruleIsProxy(r.interface)" class="row" style="gap: 4px; flex-wrap: wrap">
                  <span v-for="(n, i) in ruleProxyKeys(r.interface)" :key="n"
                        class="row" style="gap: 4px; padding: 2px 6px; border: 1px solid var(--border); border-radius: 12px; font-size: 11px"
                        :title="proxyStatusLabel(n)">
                    <span>{{ n }}</span>
                    <span class="muted">{{ proxyStatusBadge(n) }}</span>
                    <span v-if="i < ruleProxyKeys(r.interface).length - 1" class="muted">·</span>
                  </span>
                </div>
                <div v-else-if="r.action === 'route' && ruleIsXray(r.interface)" class="row" style="gap: 4px; flex-wrap: wrap">
                  <span v-for="(n, i) in ruleXrayNames(r.interface)" :key="n"
                        class="row" style="gap: 4px; padding: 2px 6px; border: 1px solid var(--border); border-radius: 12px; font-size: 11px"
                        :title="xrayStatusLabel(n)">
                    <span>xray:{{ n }}</span>
                    <span class="muted">{{ xrayStatusBadge(n) }}</span>
                    <span v-if="i < ruleXrayNames(r.interface).length - 1" class="muted">·</span>
                  </span>
                </div>
                <code v-else-if="r.action === 'route'" style="font-size: 12px">{{ r.interface }}</code>
                <span v-else class="muted">—</span>

                <!-- Exit IP: the public IP this pattern's traffic appears
                     to come from. Fetched automatically after load; the IP
                     is masked until clicked. Hidden for block rules. -->
                <div v-if="r.action !== 'block'" class="exit-ip">
                  <span v-if="exitLoading[r.id]" class="muted">probing exit IP…</span>
                  <template v-else-if="exitInfo[r.id]">
                    <template v-if="exitInfo[r.id].probed">
                      <span v-if="flagEmoji(exitInfo[r.id].country)" class="flag">{{ flagEmoji(exitInfo[r.id].country) }}</span>
                      <code class="exit-ip-val"
                            :title="revealedExitIPs[r.id] ? 'click to mask' : 'click to reveal full IP'"
                            @click="toggleExitReveal(r.id)">
                        {{ revealedExitIPs[r.id] ? exitInfo[r.id].exitIp : maskIP(exitInfo[r.id].exitIp) }}
                      </code>
                      <span v-if="exitInfo[r.id].city" class="muted">· {{ exitInfo[r.id].city }}</span>
                    </template>
                    <span v-else class="muted" :title="exitInfo[r.id].message">— couldn't determine</span>
                    <button class="link-btn" title="Re-probe exit IP" @click="checkExitIP(r)">↻</button>
                  </template>
                  <span v-else class="muted">queued…</span>
                </div>
              </td>
              <td>
                <label class="toggle" @click.prevent="toggle(r)">
                  <input type="checkbox" :checked="r.enabled" />
                  <span class="track"></span>
                </label>
              </td>
              <td style="white-space: nowrap">
                <button @click="beginEdit(r)" style="margin-right: 4px">Edit</button>
                <button
                  :class="pendingDelete === r.id ? 'danger primary' : 'danger'"
                  @click="askDelete(r)"
                >
                  {{ pendingDelete === r.id ? 'Confirm?' : 'Delete' }}
                </button>
              </td>
            </tr>

            <tr v-else class="edit-row">
              <td colspan="6">
                <div class="edit-card">
                  <div class="row" style="gap: 8px">
                    <input v-model="editing!.pattern"
                           placeholder="Pattern (e.g. *.bad.com or 1.2.3.0/24)"
                           style="flex: 1"
                           @keyup.enter="saveEdit"
                           @keyup.esc="cancelEdit" />
                    <select v-model="editing!.action" style="width: 100px">
                      <option value="block">block</option>
                      <option value="route">route</option>
                    </select>
                    <label class="toggle">
                      <input type="checkbox" v-model="editing!.enabled" />
                      <span class="track"></span>
                    </label>
                    <button class="primary" @click="saveEdit" :disabled="!editingIsValid()">Save</button>
                    <button @click="cancelEdit">Cancel</button>
                  </div>
                  <div v-if="editing!.action === 'route'" class="col" style="gap: 10px; margin-top: 10px">
                    <div class="row" style="gap: 8px; align-items: center">
                      <span class="muted" style="font-size: 11px; min-width: 60px">via:</span>
                      <div class="row" style="gap: 0">
                        <button :class="['seg', {active: editing!.binding === 'iface'}]" @click="editing!.binding = 'iface'">Interface</button>
                        <button :class="['seg', {active: editing!.binding === 'proxy'}]" @click="editing!.binding = 'proxy'">Proxy</button>
                        <button :class="['seg', {active: editing!.binding === 'xray'}]" @click="editing!.binding = 'xray'">Xray</button>
                      </div>
                      <select v-if="editing!.binding === 'iface'" v-model="editing!.iface" style="flex: 1">
                        <option value="">— pick interface —</option>
                        <option v-for="i in interfaces" :key="i.name" :value="i.name">{{ ifaceLabel(i) }} (mtu {{ i.mtu }})</option>
                        <option v-if="editing!.iface && !interfaces.some(i => i.name === editing!.iface)"
                                :value="editing!.iface" disabled>{{ editing!.iface }} — down (saved)</option>
                      </select>
                      <span v-else-if="editing!.binding === 'proxy'" class="muted" style="font-size: 11px; flex: 1">
                        select one or more — daemon uses the first one that's reachable
                        <span v-if="editing!.proxies.length" style="color: var(--accent); font-weight: 600">
                          · {{ editing!.proxies.length }} selected
                        </span>
                      </span>
                      <span v-else class="muted" style="font-size: 11px; flex: 1">
                        select one or more xray outbounds — daemon uses the first that dials
                        <span v-if="editing!.xrays.length" style="color: var(--accent); font-weight: 600">
                          · {{ editing!.xrays.length }} selected
                        </span>
                      </span>
                    </div>
                    <div v-if="editing!.binding === 'proxy'" class="chip-grid">
                      <button v-for="p in proxies" :key="p.id"
                              :class="['app-chip', {active: editing!.proxies.includes(p.name)}]"
                              @click="toggleEditingProxy(p.name)"
                              :title="`${p.protocol}://${p.host}:${p.port}`">
                        <span>{{ p.name }}</span>
                        <span class="muted" style="font-size: 10px">{{ p.protocol }}</span>
                        <span v-if="editing!.proxies.includes(p.name)" class="chip-rank">{{ editing!.proxies.indexOf(p.name) + 1 }}</span>
                      </button>
                      <span v-if="proxies.length === 0" class="muted" style="font-size: 11px; padding: 4px">
                        No proxies configured. Add one in the Proxies tab.
                      </span>
                    </div>
                    <div v-if="editing!.binding === 'xray'" class="chip-grid">
                      <button v-for="x in xrays" :key="x.id"
                              :class="['app-chip', {active: editing!.xrays.includes(x.name), 'not-running': !x.enabled}]"
                              @click="toggleEditingXray(x.name)"
                              :title="x.enabled ? `127.0.0.1:${x.socksPort}` : 'disabled'">
                        <span>{{ x.name }}</span>
                        <span class="muted" style="font-size: 10px">xray</span>
                        <span v-if="editing!.xrays.includes(x.name)" class="chip-rank">{{ editing!.xrays.indexOf(x.name) + 1 }}</span>
                      </button>
                      <span v-if="xrays.length === 0" class="muted" style="font-size: 11px; padding: 4px">
                        No xray outbounds configured. Add one in the Xray tab.
                      </span>
                    </div>
                  </div>
                </div>
              </td>
            </tr>
          </template>
        </tbody>
      </table>
    </div>
  </div>
</template>

